"""Build the static i4Seer publisher hub. Run: python scripts/build_site.py"""
from pathlib import Path
import hashlib,html,json,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]
SERIES=json.loads((ROOT/'data/series.json').read_text(encoding='utf-8'))
BASE='https://www.i4seer.com';ROUTES=[]
e=lambda text:html.escape(str(text),quote=True)
def save(path,text):
    path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text,encoding='utf-8',newline='\n')
def version(path):return path+'?v='+hashlib.sha256((ROOT/path.lstrip('/')).read_bytes()).hexdigest()[:12]
def brand():return '<a class="brand" href="/" aria-label="i4Seer home"><span class="brand-main">i4Seer</span><span class="brand-sub">SEER PRESS</span></a>'
def header(active):
    return '<header class="site-header"><div class="shell header-inner">'+brand()+'<button class="menu-btn" type="button" aria-expanded="false" aria-controls="main-nav">Menu</button><nav class="main-nav" id="main-nav" aria-label="Main navigation">'+''.join(f'<a href="{url}"'+(' aria-current="page"' if label.lower()==active else '')+f'>{label}</a>' for url,label in [('/','Home'),('/series/','Series'),('/about/','About'),('/press/','Press')])+'</nav></div></header>'
def footer():
    return '<footer class="footer"><div class="shell footer-grid"><div>'+brand()+'<p>Independent fiction.<br>Many ways to see.</p><p class="footer-small">Seer Press is an imprint of<br>Institute for Seer LLC.</p></div><div><h2>Find your next story</h2>'+''.join(f'<a href="{s["website"]}" target="_blank" rel="noopener">{e(s["name"])} ↗</a>' for s in SERIES)+'</div><div><h2>Seer Press</h2><a href="/series/">Explore the series</a><a href="/about/">About &amp; author</a><a href="/press/">Press room</a><a href="/press/#review-copies">Review copies &amp; rights</a><a href="mailto:press@i4seer.com">press@i4seer.com</a></div><div><h2>Information</h2>'+''.join(f'<a href="/{slug}/">{label}</a>' for slug,label in [('privacy','Privacy'),('terms','Terms'),('cookie-policy','Cookies'),('affiliate-disclosure','Affiliate disclosure'),('do-not-sell','Do not sell or share')])+'</div></div><div class="shell footer-meta"><span>© 2026 Institute for Seer LLC · Published by Seer Press.</span><span>There’s always more to see.</span></div></footer>'
def page(route,title,description,content,active='',extra_class='',noindex=False):
    canonical=BASE+route;image=BASE+version('/images/series/seer-worlds-20261022.webp')
    schema={'@context':'https://schema.org','@type':'Organization','name':'Seer Press','legalName':'Institute for Seer LLC','url':BASE+'/','email':'press@i4seer.com'} if route=='/' else None
    structured='<script type="application/ld+json">'+json.dumps(schema)+'</script>' if schema else ''
    document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — i4Seer · Seer Press</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#0b1821"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="i4Seer · Seer Press"><meta property="og:title" content="{e(title)} — Seer Press"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{image}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/images/favicon-i4seer.svg" type="image/svg+xml"><link rel="alternate icon" href="/favicon.ico"><link rel="stylesheet" href="{version('/style.css')}">{structured}<script defer data-domain="i4seer.com" src="https://plausible.io/js/script.js"></script><script defer src="{version('/site.js')}"></script></head><body><a class="skip" href="#main">Skip to content</a>'''+header(active)+f'<main id="main" class="{extra_class}">'+content+'</main>'+footer()+'</body></html>\n'
    save(ROOT/'404.html' if route=='/404.html' else ROOT/route.strip('/')/'index.html',document)
    if not noindex:ROUTES.append(route)
def hero(eyebrow,title,description):return f'<section class="subhero"><div class="shell"><p class="eyebrow light">{e(eyebrow)}</p><h1>{title}</h1><p class="lede">{e(description)}</p></div></section>'
def art(s):return f'<img src="{version(s["image"])}" width="{s["width"]}" height="{s["height"]}" alt="{e(s["alt"])}" loading="lazy" decoding="async">'
def card(s,mode='home'):
    out=f'<article class="series-card series-{s["slug"]}" id="{s["slug"]}"><a class="series-visual" href="{s["website"]}" target="_blank" rel="noopener" aria-label="Visit {e(s["name"])}">{art(s)}</a><div class="series-card-body"><p class="eyebrow">{e(s["category"])}</p><h3><a href="{s["website"]}" target="_blank" rel="noopener">{e(s["name"])}</a></h3><p class="series-tagline">{e(s["tagline"])}</p><p class="series-description">{e(s["description"])}</p>'
    if mode=='directory':out+=f'<p class="series-reader">{e(s["readerHook"])}</p><ul class="series-chips" aria-label="What to expect">'+''.join(f'<li>{e(v)}</li>' for v in s['highlights'])+'</ul><p class="audience-label"><strong>Readers:</strong> '+e(s['audience'])+'</p>'
    out+=f'<div class="series-actions"><a class="text-link" href="{s["website"]}" target="_blank" rel="noopener">'+('Visit the series site' if mode=='press' else e(s['cta']))+' <span aria-hidden="true">↗</span></a>'
    out+=f'<a class="asset-link" href="{version(s["image"])}" download="{s["slug"]}-series-artwork.webp">Download artwork ↓</a>' if mode=='press' else f'<span class="site-address">{e(s["host"])}</span>'
    return out+'</div></div></article>'
def grid(mode='home'):return '<div class="series-grid '+('press-grid' if mode=='press' else 'series-directory' if mode=='directory' else '')+'">'+''.join(card(s,mode) for s in SERIES)+'</div>'
AUTHOR='''<article class="author-note"><p class="eyebrow">In the author’s words</p><h2>About the author</h2><p>I write the kind of books I enjoy — full of wonder, big questions, and just enough answers to keep the pages turning.</p><p>When I’m not writing, I’m usually reading, walking, or staring at the sky, letting a new idea take shape.</p><p>I live with too many books, not enough shelves, and a strong policy of leaving the hall light on.</p><p>Thanks for joining the journey. There’s always more to see.</p><p class="signature">B. Carter</p></article>'''
BOILERPLATE='Seer Press is the independent publishing imprint of Institute for Seer LLC. Its original fiction spans fantasy, adventure, dark folklore, horror, mystery, and suspense. Written by B. Carter, its collections include Seer Worlds, Journey, Seer Frights, Seer Warns, Seer Fairies, and Seer Stories. Each has a dedicated website with current books, publication news, and available editions.'
BIO='B. Carter writes fiction full of wonder, big questions, and just enough answers to keep the pages turning. The Seer Press catalog includes fantasy, adventure, dark folklore, horror, mystery, and suspense.'

home='''<section class="home-hero"><div class="shell publisher-hero"><div class="hero-copy"><p class="eyebrow light">Independent fiction · Seer Press</p><h1>Find your kind<br>of <em>strange.</em></h1><p class="hero-lede">Impossible worlds. Forgotten rules. Ordinary lives with extraordinary consequences. Follow your curiosity into a story that stays with you.</p><div class="button-row"><a class="btn btn-gold" href="#series">Explore the series →</a><a class="btn btn-line" href="/about/#author">Meet B. Carter</a></div></div><figure class="hero-mark"><img class="hero-dot" src="'''+version('/images/seer-worlds-dot-black.png')+'''" width="512" height="512" alt="The glossy black Dot reflecting a sunset landscape" fetchpriority="high"><figcaption>The Dot · Seer Worlds</figcaption></figure></div></section>'''
home+='<section class="series-jump"><div class="shell"><span>Choose a world</span><nav aria-label="Jump to a series">'+''.join(f'<a href="#{s["slug"]}">{e(s["name"])}</a>' for s in SERIES)+'</nav></div></section>'
home+='<section class="section" id="series"><div class="shell"><div class="section-heading"><div><p class="eyebrow">The Seer Press collection</p><h2>Many places to begin.</h2></div><p>Choose the feeling that draws you in. Each collection has its own home, with book details, publication news, and available editions.</p></div>'+grid()+'</div></section>'
home+='''<section class="section section-paper"><div class="shell publisher-note"><div><p class="eyebrow">From B. Carter</p><blockquote>“I write the kind of books I enjoy — full of wonder, big questions, and just enough answers to keep the pages turning.”</blockquote><p class="signature">B. Carter</p></div><div><h2>There’s always<br>more to see.</h2><p>Seer Press brings together stories of discovery, unease, and the choices people make when the familiar stops making sense.</p><a class="text-link" href="/about/">About the press &amp; author →</a></div></div></section><section class="section"><div class="shell press-callout"><div><p class="eyebrow">For reviewers, booksellers &amp; press</p><h2>The stories behind<br>the stories.</h2><p>Find series summaries, current artwork, publisher information, and a direct line for review copies and rights inquiries.</p></div><a class="btn btn-navy" href="/press/">Visit the press room →</a></div></section>'''
page('/','Find your next story','Discover Seer Worlds, Journey, Seer Frights, Seer Warns, Seer Fairies, and Seer Stories. Original fiction by B. Carter, published by Seer Press.',home,'home')
directory=hero('Explore the collection','Follow what<br><em>draws you in.</em>','Wonder, adventure, a good scare, or a question that will not leave you alone. Find your next collection here, then continue to its dedicated website.')
directory+='<section class="section"><div class="shell"><div class="section-heading"><div><p class="eyebrow">A shelf for every curiosity</p><h2>Different stories.<br>A shared sense of wonder.</h2></div><p>Compare the premise, tone, and reading order. Each site carries the full catalog and current publication details.</p></div>'+grid('directory')+'</div></section>'
page('/series/','Series & collections','Compare all six Seer Press collections by premise, audience, and reading experience. Visit their independent websites for books, news, and editions.',directory,'series')
about=hero('Institute for Seer · Seer Press','Books that leave<br><em>something with you.</em>','Independent fiction, distinctive collections, and a lasting curiosity about the world.')
about+='''<section class="section"><div class="shell split-copy"><div><p class="eyebrow">The press</p><h2>Many stories.<br>One independent press.</h2></div><div class="prose"><p>Seer Press is the publishing imprint of Institute for Seer LLC. Its catalog spans fantasy, adventure, folklore, horror, mystery, and suspense.</p><p>Each collection has a character of its own. Seer Worlds follows a curious traveler through impossible places. Journey grows with a boy and his map. Frights and Fairies find danger close to home. Warns follows the consequences of a choice. Stories opens a different life with every book.</p><p>The dedicated sites give those books room to be themselves. Here, you can discover the collections, meet the author, and find the press.</p><a class="text-link" href="/series/">Explore the collections →</a></div></div></section><section class="section section-paper" id="author"><div class="shell author-layout">'''+AUTHOR+'''<aside><p class="eyebrow">B. Carter · Seer Press</p><h2>Leave the<br>hall light on.</h2><p>For reader correspondence, write to <a href="mailto:authors@i4seer.com">authors@i4seer.com</a>.</p><p>For reviews, interviews, rights, and publishing inquiries, contact <a href="mailto:press@i4seer.com">press@i4seer.com</a>.</p><a class="text-link" href="/press/">Press information →</a></aside></div></section>'''
page('/about/','About the press & author','Meet B. Carter and Seer Press, the independent publishing imprint of Institute for Seer LLC.',about,'about')
press=hero('The Seer Press room','Good stories.<br><em>Useful resources.</em>','Current series artwork, concise background, and contacts for reviews, interviews, and rights inquiries.')
press+='''<nav class="page-jump shell" aria-label="Press resources"><a href="#publisher">Publisher</a><a href="#series-artwork">Series &amp; artwork</a><a href="#author-bio">Author</a><a href="#review-copies">Contact</a></nav><section class="section" id="publisher"><div class="shell split-copy"><div><p class="eyebrow">Publisher boilerplate</p><h2>Seer Press</h2></div><div class="prose"><p>'''+BOILERPLATE+'''</p><a class="text-link" href="/press/seer-press-background.txt" download>Download publisher &amp; author background ↓</a></div></div></section><section class="section section-paper" id="series-artwork"><div class="shell"><div class="section-heading"><div><p class="eyebrow">Series reference &amp; downloads</p><h2>Current worlds.<br>Current artwork.</h2></div><p>These images match the latest series websites. Download the WebP artwork below; contact the press for cover originals, logos, or print-ready files.</p></div>'''+grid('press')+'''</div></section><section class="section" id="author-bio"><div class="shell split-copy"><div><p class="eyebrow">Author background</p><h2>B. Carter</h2></div><div class="prose"><p>'''+BIO+'''</p><blockquote class="small-quote">“I live with too many books, not enough shelves, and a strong policy of leaving the hall light on.”</blockquote><a class="text-link" href="/about/#author">Read the author’s note →</a></div></div></section><section class="section section-paper"><div class="shell split-copy"><div><p class="eyebrow">Names &amp; credits</p><h2>For your reference.</h2></div><div class="prose"><p><strong>Seer Press</strong> is the publishing imprint. <strong>Institute for Seer LLC</strong> is the legal entity. <strong>i4Seer</strong> uses a lowercase “i,” numeral “4,” and capitalized “Seer.”</p><p>The collections are <strong>Seer Worlds, Seer Frights, Seer Warns, Seer Fairies, Seer Stories,</strong> and <strong>Journey</strong>. Journey is one word, without a “Seer” prefix.</p><p>Please credit series artwork to Seer Press. For book-specific artwork, edition information, or additional usage requests, contact the press.</p></div></div></section><section class="section contact-section" id="review-copies"><div class="shell press-callout"><div><p class="eyebrow light">Reviews · interviews · rights</p><h2>A direct line to the press.</h2><p>Tell us the title or series, your outlet, the material you need, and any deadline.</p></div><a class="btn btn-gold" href="mailto:press@i4seer.com">press@i4seer.com ↗</a></div></section>'''
page('/press/','Press room','Seer Press publisher and author background, current artwork for all six collections, and contacts for review copies, interviews, and rights.',press,'press')
save(ROOT/'press/seer-press-background.txt','SEER PRESS\n\n'+BOILERPLATE+'\n\nB. CARTER\n\n'+BIO+'\n\nPRESS CONTACT\npress@i4seer.com\nhttps://www.i4seer.com/press/\n\nCOLLECTION WEBSITES\n'+''.join(s['name']+': '+s['website']+'\n' for s in SERIES))
for legal in json.loads((ROOT/'data/legal-pages.json').read_text(encoding='utf-8')):
    page('/'+legal['slug']+'/',html.unescape(legal['title']).rstrip('.'),html.unescape(legal['description']),legal['body'],extra_class='legal-content')
page('/404.html','Page not found','Return to the Seer Press collections.',hero('A page out of place · 404','Another way<br><em>into the story.</em>','The page you are looking for could not be found.')+'<section class="section"><div class="shell button-row"><a class="btn btn-navy" href="/series/">Explore the collections →</a><a class="text-link" href="/">Back home</a></div></section>',noindex=True)
redirects=[('/standalone/','https://stories.i4seer.com/','Seer Stories'),('/series/seer-fairies/','https://fairies.i4seer.com/','Seer Fairies'),('/books/','/series/','the collections')]
for route,target,name in redirects:
    canonical=BASE+target if target.startswith('/') else target
    save(ROOT/route.strip('/')/'index.html',f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Continue to {e(name)} — Seer Press</title><meta name="robots" content="noindex,follow"><link rel="canonical" href="{canonical}"><meta http-equiv="refresh" content="0; url={target}"></head><body><main><h1>{e(name)} has a new home.</h1><p><a href="{target}">Continue to {e(name)} →</a></p></main></body></html>\n')
cfg=json.loads((ROOT/'staticwebapp.config.json').read_text(encoding='utf-8'))
old_routes={v for p,_,_ in redirects for v in [p,p.rstrip('/')]}
cfg['routes']=[{'route':v,'redirect':target,'statusCode':301} for p,target,_ in redirects for v in [p.rstrip('/'),p]]+[r for r in cfg['routes'] if r['route'] not in old_routes]
save(ROOT/'staticwebapp.config.json',json.dumps(cfg,indent=2)+'\n')
xml=ET.Element('urlset',xmlns='http://www.sitemaps.org/schemas/sitemap/0.9')
for route in ROUTES:ET.SubElement(ET.SubElement(xml,'url'),'loc').text=BASE+route
save(ROOT/'sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n'+ET.tostring(xml,encoding='unicode')+'\n')
save(ROOT/'robots.txt','User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
print(f'Built {len(ROUTES)+1} pages and three legacy redirects; {len(SERIES)} independent collection websites.')
